const q = (s) => "'" + String(s).replace(/'/g, "''") + "'";
function rootExpr(name){return "SELECT id FROM deployment.infra_node WHERE parent_id=id AND node_type='droplet' AND name="+q(name);}
function childExpr(parentExpr,ntype,cname){return "SELECT id FROM deployment.infra_node WHERE parent_id=("+parentExpr+") AND node_type="+q(ntype)+" AND name="+q(cname);}
function upsert(parentExpr,ntype,name,version,attrs){
  const v=(version===null||version===undefined||version==='')?'NULL':q(version);
  const a=q(JSON.stringify(attrs||{}))+'::jsonb';
  return "INSERT INTO deployment.infra_node (parent_id, node_type, name, version, attrs, source, status, last_scanned, last_changed) VALUES (("+parentExpr+"), "+q(ntype)+", "+q(name)+", "+v+", "+a+", 'probed', 'live', now(), now()) ON CONFLICT (parent_id, node_type, name) DO UPDATE SET last_scanned=now(), last_changed=CASE WHEN deployment.infra_node.version IS DISTINCT FROM EXCLUDED.version THEN now() ELSE deployment.infra_node.last_changed END, version=EXCLUDED.version, attrs=deployment.infra_node.attrs||EXCLUDED.attrs, updated_at=now(), updated_by='infra-probe' WHERE deployment.infra_node.source <> 'manual';";
}
function updateRootOs(name,os){return "UPDATE deployment.infra_node SET version=CASE WHEN version IS DISTINCT FROM "+q(os)+" THEN "+q(os)+" ELSE version END, last_changed=CASE WHEN version IS DISTINCT FROM "+q(os)+" THEN now() ELSE last_changed END, last_scanned=now(), updated_at=now(), updated_by='infra-probe' WHERE id=("+rootExpr(name)+") AND source<>'manual';";}
function parseAndBuild(machine,blob){
  const sql=[]; const rootE=rootExpr(machine);
  const pgParent=childExpr(rootE,'postgres','postgres');
  const caddyParent=childExpr(rootE,'caddy','caddy');
  const lines=String(blob||'').split('\n').map(l=>l.trim()).filter(Boolean);
  for(const line of lines){
    const parts=line.split('|'); const tag=parts[0];
    if(tag==='OS'&&parts[1])sql.push(updateRootOs(machine,parts[1]));
    else if(tag==='PG'&&parts[1])sql.push(upsert(rootE,'postgres','postgres',parts[1],{}));
    else if(tag==='DB'&&parts[1])sql.push(upsert(pgParent,'database',parts[1],null,{}));
    else if(tag==='N8N'&&parts[1])sql.push(upsert(rootE,'n8n','n8n',parts[1],{}));
    else if(tag==='NODE'&&parts[1])sql.push(upsert(rootE,'node','node',parts[1],{}));
    else if(tag==='CADDY'&&parts[1])sql.push(upsert(rootE,'caddy','caddy',parts[1],{}));
    else if(tag==='ROUTE'&&parts[1]){const up=parts[2]||'';const port=up.includes(':')?up.split(':').pop():'';sql.push(upsert(caddyParent,'route',parts[1],null,{upstream:up,upstream_port:port}));}
  }
  return sql;
}
const devBlob=$('Probe Dev').first().json.stdout||'';
const prodBlob=$('Probe Prod').first().json.stdout||'';
let statements=[];
statements=statements.concat(parseAndBuild('dev',devBlob));
statements=statements.concat(parseAndBuild('prod',prodBlob));
if(statements.length===0){throw new Error('infra-probe: both probe blobs parsed to zero statements - refusing to write (fail loud).');}
return [{json:{sql:statements.join('\n')}}];
